// Normalise the WhatsApp Trigger payload to { wa_number, text, name }.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  // The trigger may emit a simplified message or the raw Meta value object.
  const messages = j.messages || (j.value && j.value.messages) || [];
  const contacts = j.contacts || (j.value && j.value.contacts) || [];
  const nameByWa = {};
  for (const c of contacts) nameByWa[c.wa_id] = (c.profile || {}).name;
  if (messages.length) {
    for (const m of messages) {
      if (m.type && m.type !== 'text') continue;
      out.push({ json: { wa_number: m.from, text: (m.text && m.text.body) || m.body || '', name: nameByWa[m.from] || null } });
    }
  } else if (j.from && (j.text || j.body)) {
    out.push({ json: { wa_number: j.from, text: (j.text && j.text.body) || j.body || '', name: j.name || null } });
  }
}
return out; // empty array => status/non-text events stop here (no call to the app)
